CREATE TABLE el_invoice_print_settings(org_id TEXT PRIMARY KEY REFERENCES el_organizations(id),issuer_name TEXT NOT NULL DEFAULT '' CHECK(length(issuer_name)<=160),contact_text TEXT NOT NULL DEFAULT '' CHECK(length(contact_text)<=600),invoice_footer TEXT NOT NULL DEFAULT '' CHECK(length(invoice_footer)<=1000),receipt_footer TEXT NOT NULL DEFAULT '' CHECK(length(receipt_footer)<=1000),accent TEXT NOT NULL DEFAULT 'blue' CHECK(accent IN ('blue','navy','teal')),updated_at INTEGER NOT NULL);
CREATE TABLE el_invoice_print_snapshots(invoice_id TEXT PRIMARY KEY,org_id TEXT NOT NULL,issuer_name TEXT NOT NULL,contact_text TEXT NOT NULL,invoice_footer TEXT NOT NULL,receipt_footer TEXT NOT NULL,accent TEXT NOT NULL CHECK(accent IN ('blue','navy','teal')),captured_at INTEGER NOT NULL,FOREIGN KEY(org_id,invoice_id) REFERENCES el_invoices(org_id,id));
CREATE TRIGGER el_invoice_print_snapshot_insert BEFORE INSERT ON el_invoice_print_snapshots BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM el_invoices i WHERE i.id=NEW.invoice_id AND i.org_id=NEW.org_id AND i.status='draft') THEN RAISE(ABORT,'Print snapshot requires a draft invoice') END; END;
CREATE TRIGGER el_invoice_print_snapshot_update BEFORE UPDATE ON el_invoice_print_snapshots BEGIN SELECT RAISE(ABORT,'Invoice print snapshot is immutable'); END;
CREATE TRIGGER el_invoice_print_snapshot_delete BEFORE DELETE ON el_invoice_print_snapshots WHEN COALESCE((SELECT is_demo FROM el_invoices WHERE id=OLD.invoice_id),0)=0 BEGIN SELECT RAISE(ABORT,'Invoice print snapshot is immutable'); END;
CREATE TRIGGER el_invoice_print_issue BEFORE UPDATE OF status ON el_invoices WHEN OLD.status='draft' AND NEW.status='issued' AND NEW.is_demo=0 BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM el_invoice_print_snapshots p WHERE p.invoice_id=NEW.id AND p.org_id=NEW.org_id) THEN RAISE(ABORT,'Invoice print snapshot is required') END; END;
